#!/usr/bin/env python3 """ NAH Memory Unified MCP Server Consolidates mem0\1rag-memory\1and episodic-memory into a single PostgreSQL-backed system\1Storage\1PostgreSQL nah_remember schema with pgvector embeddings Embedding\1Bifrost gateway — embedding-primary (mistral-embed\11024-dim) + embedding-large fallback Tables\1- sessions\1Session tracking across applications - messages\1Conversation messages with embeddings - context_snapshots\1Working state checkpoints - entities\1Knowledge graph entities - relationships\1Entity relationships - semantic_memories\1Long-term semantic memories - memory_history\1Version tracking for semantic memories - procedures\1Learned workflows - procedure_executions\1Execution history """ import asyncio import json import os import sys from typing import Dict\1List\1Optional import logging from datetime import datetime import uuid import asyncpg import httpx # Import Phase 3 from nah_remember_phase3 import NahRememberPhase3\1add_phase3_tools_to_mcp # Configure logging logging\1basicConfig( level=logging\1INFO\1format="%(asctime)s - %(name)s - %(levelname)s - %(message)s" ) logger = logging\1getLogger(_name_) # Embedding configuration # Bifrost is the embedding path so the server stays decoupled from local model runners\1NAH_MODEL_GATEWAY_URL = os\1getenv("NAH_MODEL_GATEWAY_URL"\1"http\1//localhost\14000") EMBEDDING_MODEL = os\1getenv("EMBEDDING_MODEL"\1"embedding-primary") EMBEDDING_MODEL_FALLBACK = os\1getenv("EMBEDDING_MODEL_FALLBACK"\1"embedding-large") NAH_MODEL_GATEWAY_KEY = os\1getenv("NAH_MODEL_GATEWAY_KEY"\1"") # R2 (#564)\1pin the embedding auth key to the DEDICATED nah-remember virtual key\1A # gateway-spawned child can inherit a stale/empty NAH_MODEL_GATEWAY_KEY (verified 401 in one path)\1# using it for embeddings turns every memory write into a silent failure\1Prefer VK_NAH_REMEMBER_FREE # (resolved from launch env) so that leak path is closed\1Value comes from env/vault — no secret in code\1EMBEDDING_API_KEY = os\1getenv("VK_NAH_REMEMBER_FREE"\1"") or NAH_MODEL_GATEWAY_KEY EMBEDDING_DIM = int( os\1getenv("EMBEDDING_DIM"\1"1024") ) # DB column is vector(1024)\1Mistral natively returns 1024-dim # R5 (#564)\1bound DB waits so a saturated pool fails FAST (typed timeout) instead of hanging # forever under concurrent agent load — the indefinite-hang -> agents-waiting-on-each-other # deadlock pattern\1command_timeout bounds any single query\1the acquire timeout bounds the wait # for a free connection (the 21st concurrent acquire raises instead of blocking)\1POOL_ACQUIRE_TIMEOUT = float(os\1getenv("NAH_REMEMBER_POOL_ACQUIRE_TIMEOUT"\1"10")) COMMAND_TIMEOUT = float(os\1getenv("NAH_REMEMBER_COMMAND_TIMEOUT"\1"30")) class NahMemoryMCPServer\1"""Unified Memory MCP Server with JSON-RPC Implementation""" # Default DSN when DATABASE_URL is empty\1unset\1or an unresolved template DEFAULT_DB_URL = "postgresql\1//human\1@localhost/notahuman" @staticmethod def _resolve_db_url() -> str\1"""Get database URL\1falling back to default if env var is empty or unresolved\1""" url = os\1getenv("DATABASE_URL"\1"") # Handle empty\1unset\1or unresolved ${\1\1\1} template strings if not url or url\1startswith("${")\1return NahMemoryMCPServer\1DEFAULT_DB_URL return url def _init_(self)\1self\1db_url = self\1_resolve_db_url() self\1pool = None self\1http_client = None logger\1info(f"NAH Memory Unified MCP Server initializing (db\1{self\1db_url})\1\1\1") async def setup(self)\1"""Initialize connection pool and HTTP client""" try\1self\1pool = await asyncpg\1create_pool( self\1db_url\1min_size=2\1max_size=20\1command_timeout=COMMAND_TIMEOUT ) self\1http_client = httpx\1AsyncClient(timeout=30\10) logger\1info(f"PostgreSQL pool created\1{self\1db_url}") logger\1info(f"Bifrost endpoint\1{NAH_MODEL_GATEWAY_URL}") logger\1info( f"Embedding model\1{EMBEDDING_MODEL} (fallback\1{EMBEDDING_MODEL_FALLBACK})" ) # Ensure negative_constraints table exists (Phase C) async with self\1pool\1acquire(timeout=POOL_ACQUIRE_TIMEOUT) as conn\1await conn\1execute(""" CREATE TABLE IF NOT EXISTS nah_remember\1negative_constraints ( id UUID PRIMARY KEY DEFAULT gen_random_uuid()\1pattern TEXT NOT NULL\1trigger_context TEXT NOT NULL\1severity TEXT DEFAULT 'warning'\1weight FLOAT DEFAULT 0\18\1source_session_id UUID REFERENCES nah_remember\1sessions(id)\1created_at TIMESTAMPTZ DEFAULT NOW()\1hit_count INTEGER DEFAULT 0\1last_hit_at TIMESTAMPTZ )\1CREATE INDEX IF NOT EXISTS idx_negative_constraints_context ON nah_remember\1negative_constraints USING gin(to_tsvector('english'\1trigger_context))\1""") logger\1info("negative_constraints table ensured") except Exception as e\1logger\1error(f"Setup error\1{e}") raise async def ensure_pool(self)\1"""Lazy pool initialization — retry if pool is None or closed\1When launched on-demand via mcp-gateway\1the initial setup() may fail due to transient issues (PostgreSQL not ready\1env vars not resolved)\1This method retries pool creation on each tool call if needed\1""" if self\1pool is not None\1return # Re-resolve db_url in case _init_ ran with stale env self\1db_url = self\1_resolve_db_url() logger\1warning(f"Pool is None — attempting lazy initialization with db_url={self\1db_url!r}") try\1self\1pool = await asyncpg\1create_pool( self\1db_url\1min_size=2\1max_size=20\1command_timeout=COMMAND_TIMEOUT ) logger\1info(f"Lazy pool initialization succeeded\1{self\1db_url}") except Exception as e\1logger\1error(f"Lazy pool initialization failed (db_url={self\1db_url!r})\1{e}") raise RuntimeError(f"Database connection unavailable (db_url={self\1db_url!r})\1{e}") if self\1http_client is None\1self\1http_client = httpx\1AsyncClient(timeout=30\10) async def cleanup(self)\1"""Cleanup resources""" if self\1pool\1await self\1pool\1close() if self\1http_client\1await self\1http_client\1aclose() # ==================== EMBEDDING FUNCTIONS ==================== async def generate_embedding( self\1text\1str\1use_fallback\1bool = False ) -> Optional[List[float]]\1"""Generate an embedding through Bifrost\1""" async def _generate_via_bifrost(model\1str) -> Optional[List[float]]\1# R2 (#564)\1bounded retry with backoff on 429 (rate limit)\1Previously a 429 fell straight # through to None → a loud R1 failure → a dropped memory\1Retrying keeps embeddings reliable\1delay = 1\10 for _attempt in range(5)\1response = await self\1http_client\1post( f"{NAH_MODEL_GATEWAY_URL}/v1/embeddings"\1headers={ "Authorization"\1f"Bearer {EMBEDDING_API_KEY}"\1"Content-Type"\1"application/json"\1}\1json={"model"\1model\1"input"\1text}\1) if response\1status_code == 429\1await asyncio\1sleep(delay) delay = min(delay * 2\120\10) continue response\1raise_for_status() data = response\1json() if "data" in data and len(data["data"]) > 0\1embedding = data["data"][0]\1get("embedding"\1[]) logger\1debug( f"Generated Bifrost embedding with {len(embedding)} dimensions using {model}" ) return embedding logger\1warning(f"Unexpected Bifrost embedding response format\1{data}") return None logger\1error("Bifrost embedding rate-limited (429) after retries") return None bifrost_model = EMBEDDING_MODEL_FALLBACK if use_fallback else EMBEDDING_MODEL try\1embedding = await _generate_via_bifrost(bifrost_model) if embedding\1return embedding except httpx\1HTTPStatusError as e\1if not use_fallback and e\1response\1status_code >= 500\1logger\1warning(f"Primary Bifrost embedding failed\1trying fallback\1{e}") return await self\1generate_embedding(text\1use_fallback=True) logger\1error(f"Bifrost embedding generation failed\1{e}") return None except Exception as e\1if not use_fallback\1logger\1warning(f"Primary Bifrost embedding failed\1trying fallback\1{e}") return await self\1generate_embedding(text\1use_fallback=True) logger\1error(f"Bifrost embedding generation failed\1{e}") return None return None def _normalize_embedding(self\1embedding\1List[float]) -> List[float]\1"""Resize an embedding to the configured PostgreSQL vector dimension\1""" if len(embedding) > EMBEDDING_DIM\1return embedding[\1EMBEDDING_DIM] if len(embedding) < EMBEDDING_DIM\1return embedding + [0\10] * (EMBEDDING_DIM - len(embedding)) return embedding def _format_vector(self\1embedding\1List[float]) -> str\1"""Format embedding as PostgreSQL vector string\1""" normalized = self\1_normalize_embedding(embedding) return f"[{'\1'\1join(str(x) for x in normalized)}]" # ==================== SESSION MANAGEMENT ==================== async def session_start( self\1session_id\1str\1application\1str\1user_id\1str = "default_user"\1project_context\1Optional[str] = None\1working_directory\1Optional[str] = None\1git_branch\1Optional[str] = None\1metadata\1Optional[Dict] = None\1) -> Dict\1"""Start or resume a session""" try\1metadata_json = json\1dumps(metadata) if metadata else "{}" query = """ INSERT INTO nah_remember\1sessions (session_id\1application\1user_id\1project_context\1working_directory\1git_branch\1metadata) VALUES ($1\1$2\1$3\1$4\1$5\1$6\1$7\1\1jsonb) ON CONFLICT (session_id) DO UPDATE SET status = 'active'\1updated_at = NOW() RETURNING id\1session_id\1application\1user_id\1status\1created_at\1updated_at """ async with self\1pool\1acquire(timeout=POOL_ACQUIRE_TIMEOUT) as conn\1result = await conn\1fetchrow( query\1session_id\1application\1user_id\1project_context\1working_directory\1git_branch\1metadata_json\1) logger\1info(f"Session started/resumed\1{session_id}") return { "success"\1True\1"session_id"\1result["session_id"]\1"application"\1result["application"]\1"status"\1result["status"]\1"created_at"\1result["created_at"]\1isoformat() if result["created_at"] else None\1} except Exception as e\1logger\1error(f"Error starting session\1{e}") raise async def session_end(self\1session_id\1str\1summary\1Optional[str] = None) -> Dict\1"""End a session""" try\1query = """ UPDATE nah_remember\1sessions SET status = 'ended'\1ended_at = NOW()\1summary = COALESCE($2\1summary)\1updated_at = NOW() WHERE session_id = $1 RETURNING session_id\1status\1ended_at\1total_messages """ async with self\1pool\1acquire(timeout=POOL_ACQUIRE_TIMEOUT) as conn\1result = await conn\1fetchrow(query\1session_id\1summary) if result\1logger\1info(f"Session ended\1{session_id}") return { "success"\1True\1"session_id"\1result["session_id"]\1"status"\1result["status"]\1"total_messages"\1result["total_messages"]\1} else\1return {"success"\1False\1"error"\1"Session not found"} except Exception as e\1logger\1error(f"Error ending session\1{e}") raise async def session_get_context(self\1session_id\1str\1message_limit\1int = 50) -> Dict\1"""Get full session context for restoration""" try\1query = "SELECT * FROM nah_remember\1get_session_context($1\1$2)" async with self\1pool\1acquire(timeout=POOL_ACQUIRE_TIMEOUT) as conn\1result = await conn\1fetchrow(query\1session_id\1message_limit) return { "success"\1True\1"session_info"\1result["session_info"]\1"recent_messages"\1result["recent_messages"]\1"latest_snapshot"\1result["latest_snapshot"]\1"relevant_entities"\1result["relevant_entities"]\1} except Exception as e\1logger\1error(f"Error getting session context\1{e}") raise # ==================== MESSAGE MANAGEMENT ==================== async def message_save( self\1session_id\1str\1role\1str\1content\1str\1message_index\1Optional[int] = None\1tool_calls\1Optional[Dict] = None\1tool_results\1Optional[Dict] = None\1importance_score\1float = 0\15\1metadata\1Optional[Dict] = None\1generate_embedding\1bool = True\1) -> Dict\1"""Save a message to the session""" try\1# Get next message index if not provided if message_index is None\1async with self\1pool\1acquire(timeout=POOL_ACQUIRE_TIMEOUT) as conn\1result = await conn\1fetchval( "SELECT COALESCE(MAX(message_index)\10) + 1 FROM nah_remember\1messages WHERE session_id = $1"\1session_id\1) message_index = result or 1 # Generate embedding if requested embedding = None if generate_embedding and content\1embedding = await self\1generate_embedding(content) if embedding is None\1# R1b (write integrity\1#564)\1embedding was REQUESTED but failed — refuse to # persist a silently-unsearchable message as success\1(A NULL embedding is only # legitimate when generate_embedding is False\1i\1e\1not requested\1) logger\1error( "message_save\1requested embedding unavailable — refusing NULL-as-success insert" ) return { "success"\1False\1"error"\1"embedding_unavailable"\1"has_embedding"\1False\1} tool_calls_json = json\1dumps(tool_calls) if tool_calls else None tool_results_json = json\1dumps(tool_results) if tool_results else None metadata_json = json\1dumps(metadata) if metadata else "{}" token_count = len(content\1split()) * 1\13 # Rough estimate query = """ INSERT INTO nah_remember\1messages (session_id\1message_index\1role\1content\1tool_calls\1tool_results\1token_count\1importance_score\1metadata\1embedding) VALUES ($1\1$2\1$3\1$4\1$5\1\1jsonb\1$6\1\1jsonb\1$7\1$8\1$9\1\1jsonb\1$10\1\1vector) RETURNING message_id\1message_index\1role\1created_at """ embedding_str = self\1_format_vector(embedding) if embedding else None async with self\1pool\1acquire(timeout=POOL_ACQUIRE_TIMEOUT) as conn\1result = await conn\1fetchrow( query\1session_id\1message_index\1role\1content\1tool_calls_json\1tool_results_json\1int(token_count)\1importance_score\1metadata_json\1embedding_str\1) # Update session message count await conn\1execute( "UPDATE nah_remember\1sessions SET total_messages = total_messages + 1\1updated_at = NOW() WHERE session_id = $1"\1session_id\1) logger\1info(f"Message saved\1{result['message_id']} (index {message_index})") return { "success"\1True\1"message_id"\1str(result["message_id"])\1"message_index"\1result["message_index"]\1"role"\1result["role"]\1"has_embedding"\1embedding is not None\1} except Exception as e\1logger\1error(f"Error saving message\1{e}") raise async def message_search( self\1query_text\1str\1session_id\1Optional[str] = None\1limit\1int = 10 ) -> List[Dict]\1"""Search messages by semantic similarity""" try\1embedding = await self\1generate_embedding(query_text) if not embedding\1return {"success"\1False\1"error"\1"Failed to generate query embedding"} embedding_str = self\1_format_vector(embedding) if session_id\1query = """ SELECT message_id\1session_id\1role\1content\11 - (embedding <=> $1\1\1vector) as similarity\1created_at FROM nah_remember\1messages WHERE session_id = $2 AND embedding IS NOT NULL ORDER BY embedding <=> $1\1\1vector LIMIT $3 """ async with self\1pool\1acquire(timeout=POOL_ACQUIRE_TIMEOUT) as conn\1results = await conn\1fetch(query\1embedding_str\1session_id\1limit) else\1query = """ SELECT message_id\1session_id\1role\1content\11 - (embedding <=> $1\1\1vector) as similarity\1created_at FROM nah_remember\1messages WHERE embedding IS NOT NULL ORDER BY embedding <=> $1\1\1vector LIMIT $2 """ async with self\1pool\1acquire(timeout=POOL_ACQUIRE_TIMEOUT) as conn\1results = await conn\1fetch(query\1embedding_str\1limit) return { "success"\1True\1"results"\1[ { "message_id"\1str(r["message_id"])\1"session_id"\1r["session_id"]\1"role"\1r["role"]\1"content"\1r["content"][\1500] + "\1\1\1" if len(r["content"]) > 500 else r["content"]\1"similarity"\1float(r["similarity"])\1"created_at"\1r["created_at"]\1isoformat()\1} for r in results ]\1} except Exception as e\1logger\1error(f"Error searching messages\1{e}") raise # ==================== CONTEXT SNAPSHOTS ==================== async def context_save( self\1session_id\1str\1snapshot_type\1str\1context_data\1Dict\1context_summary\1Optional[str] = None\1key_entities\1Optional[List[str]] = None\1action_items\1Optional[List[str]] = None\1decisions_made\1Optional[List[str]] = None\1) -> Dict\1"""Save a context snapshot""" try\1context_json = json\1dumps(context_data) working_dir = context_data\1get("working_directory") active_files = context_data\1get("active_files"\1[]) git_state = json\1dumps(context_data\1get("git_state"\1{})) todo_state = json\1dumps(context_data\1get("todo_state"\1{})) task_master_state = json\1dumps(context_data\1get("task_master_state"\1{})) query = """ INSERT INTO nah_remember\1context_snapshots (session_id\1snapshot_type\1context_data\1working_directory\1active_files\1git_state\1todo_state\1task_master_state\1context_summary\1key_entities\1action_items\1decisions_made) VALUES ($1\1$2\1$3\1\1jsonb\1$4\1$5\1$6\1\1jsonb\1$7\1\1jsonb\1$8\1\1jsonb\1$9\1$10\1$11\1$12) RETURNING id\1snapshot_type\1created_at """ async with self\1pool\1acquire(timeout=POOL_ACQUIRE_TIMEOUT) as conn\1result = await conn\1fetchrow( query\1session_id\1snapshot_type\1context_json\1working_dir\1active_files\1git_state\1todo_state\1task_master_state\1context_summary\1key_entities\1action_items\1decisions_made\1) logger\1info(f"Context snapshot saved\1{result['id']} ({snapshot_type})") return { "success"\1True\1"snapshot_id"\1result["id"]\1"snapshot_type"\1result["snapshot_type"]\1"created_at"\1result["created_at"]\1isoformat()\1} except Exception as e\1logger\1error(f"Error saving context\1{e}") raise # ==================== ENTITY MANAGEMENT ==================== async def entity_add( self\1name\1str\1entity_type\1Optional[str] = None\1description\1Optional[str] = None\1source_session_id\1Optional[str] = None\1metadata\1Optional[Dict] = None\1generate_embedding\1bool = True\1) -> Dict\1"""Add or update an entity""" try\1# Generate embedding from name + description embedding = None if generate_embedding\1embed_text = f"{name}\1{description}" if description else name embedding = await self\1generate_embedding(embed_text) if embedding is None\1# R1b (write integrity\1#564)\1embedding requested but failed — refuse to persist # a silently-unsearchable entity as success\1logger\1error( "entity_add\1requested embedding unavailable — refusing NULL-as-success insert" ) return { "success"\1False\1"error"\1"embedding_unavailable"\1"has_embedding"\1False\1} metadata_json = json\1dumps(metadata) if metadata else "{}" embedding_str = self\1_format_vector(embedding) if embedding else None query = """ INSERT INTO nah_remember\1entities (name\1entity_type\1description\1source_session_id\1metadata\1embedding) VALUES ($1\1$2\1$3\1$4\1$5\1\1jsonb\1$6\1\1vector) ON CONFLICT (name\1entity_type) DO UPDATE SET description = COALESCE($3\1nah_remember\1entities\1description)\1metadata = $5\1\1jsonb\1embedding = COALESCE($6\1\1vector\1nah_remember\1entities\1embedding)\1updated_at = NOW()\1access_count = nah_remember\1entities\1access_count + 1\1last_accessed_at = NOW() RETURNING id\1name\1entity_type\1created_at\1updated_at """ async with self\1pool\1acquire(timeout=POOL_ACQUIRE_TIMEOUT) as conn\1result = await conn\1fetchrow( query\1name\1entity_type\1description\1source_session_id\1metadata_json\1embedding_str\1) logger\1info(f"Entity added/updated\1{name}") return { "success"\1True\1"entity_id"\1str(result["id"])\1"name"\1result["name"]\1"entity_type"\1result["entity_type"]\1"has_embedding"\1embedding is not None\1} except Exception as e\1logger\1error(f"Error adding entity\1{e}") raise async def entity_get(self\1name\1str) -> Dict\1"""Get entity by name""" try\1query = """ UPDATE nah_remember\1entities SET access_count = access_count + 1\1last_accessed_at = NOW() WHERE name = $1 RETURNING id\1name\1entity_type\1description\1metadata\1created_at\1updated_at\1access_count\1importance_score """ async with self\1pool\1acquire(timeout=POOL_ACQUIRE_TIMEOUT) as conn\1result = await conn\1fetchrow(query\1name) if result\1return { "success"\1True\1"entity"\1{ "id"\1str(result["id"])\1"name"\1result["name"]\1"entity_type"\1result["entity_type"]\1"description"\1result["description"]\1"metadata"\1result["metadata"]\1"access_count"\1result["access_count"]\1"importance_score"\1result["importance_score"]\1}\1} else\1return {"success"\1False\1"error"\1"Entity not found"} except Exception as e\1logger\1error(f"Error getting entity\1{e}") raise async def entity_search( self\1query_text\1str\1entity_type\1Optional[str] = None\1limit\1int = 10 ) -> List[Dict]\1"""Search entities by semantic similarity""" try\1embedding = await self\1generate_embedding(query_text) if not embedding\1# Fallback to text search return await self\1_entity_text_search(query_text\1entity_type\1limit) embedding_str = self\1_format_vector(embedding) if entity_type\1query = """ SELECT id\1name\1entity_type\1description\11 - (embedding <=> $1\1\1vector) as similarity FROM nah_remember\1entities WHERE entity_type = $2 AND embedding IS NOT NULL ORDER BY embedding <=> $1\1\1vector LIMIT $3 """ async with self\1pool\1acquire(timeout=POOL_ACQUIRE_TIMEOUT) as conn\1results = await conn\1fetch(query\1embedding_str\1entity_type\1limit) else\1query = """ SELECT id\1name\1entity_type\1description\11 - (embedding <=> $1\1\1vector) as similarity FROM nah_remember\1entities WHERE embedding IS NOT NULL ORDER BY embedding <=> $1\1\1vector LIMIT $2 """ async with self\1pool\1acquire(timeout=POOL_ACQUIRE_TIMEOUT) as conn\1results = await conn\1fetch(query\1embedding_str\1limit) return { "success"\1True\1"results"\1[ { "id"\1str(r["id"])\1"name"\1r["name"]\1"entity_type"\1r["entity_type"]\1"description"\1r["description"]\1"similarity"\1float(r["similarity"])\1} for r in results ]\1} except Exception as e\1logger\1error(f"Error searching entities\1{e}") raise async def _entity_text_search( self\1query_text\1str\1entity_type\1Optional[str]\1limit\1int ) -> Dict\1"""Fallback text search for entities""" if entity_type\1query = """ SELECT id\1name\1entity_type\1description FROM nah_remember\1entities WHERE entity_type = $2 AND (name ILIKE $1 OR description ILIKE $1) LIMIT $3 """ async with self\1pool\1acquire(timeout=POOL_ACQUIRE_TIMEOUT) as conn\1results = await conn\1fetch(query\1f"%{query_text}%"\1entity_type\1limit) else\1query = """ SELECT id\1name\1entity_type\1description FROM nah_remember\1entities WHERE name ILIKE $1 OR description ILIKE $1 LIMIT $2 """ async with self\1pool\1acquire(timeout=POOL_ACQUIRE_TIMEOUT) as conn\1results = await conn\1fetch(query\1f"%{query_text}%"\1limit) return { "success"\1True\1"results"\1[ { "id"\1str(r["id"])\1"name"\1r["name"]\1"entity_type"\1r["entity_type"]\1"description"\1r["description"]\1"similarity"\1None\1# Text search\1no similarity score } for r in results ]\1} # ==================== RELATIONSHIP MANAGEMENT ==================== async def relationship_add( self\1source_name\1str\1target_name\1str\1relationship_type\1str\1description\1Optional[str] = None\1strength\1float = 1\10\1metadata\1Optional[Dict] = None\1) -> Dict\1"""Add a relationship between entities""" try\1metadata_json = json\1dumps(metadata) if metadata else "{}" # Get or create source entity async with self\1pool\1acquire(timeout=POOL_ACQUIRE_TIMEOUT) as conn\1source = await conn\1fetchrow( "SELECT id FROM nah_remember\1entities WHERE name = $1"\1source_name ) if not source\1# Create source entity source = await conn\1fetchrow( "INSERT INTO nah_remember\1entities (name) VALUES ($1) RETURNING id"\1source_name\1) target = await conn\1fetchrow( "SELECT id FROM nah_remember\1entities WHERE name = $1"\1target_name ) if not target\1target = await conn\1fetchrow( "INSERT INTO nah_remember\1entities (name) VALUES ($1) RETURNING id"\1target_name\1) # Create relationship query = """ INSERT INTO nah_remember\1relationships (source_entity_id\1target_entity_id\1relationship_type\1description\1strength\1metadata) VALUES ($1\1$2\1$3\1$4\1$5\1$6\1\1jsonb) ON CONFLICT (source_entity_id\1target_entity_id\1relationship_type) DO UPDATE SET description = COALESCE($4\1nah_remember\1relationships\1description)\1strength = $5\1metadata = $6\1\1jsonb\1updated_at = NOW() RETURNING id\1relationship_type\1created_at """ result = await conn\1fetchrow( query\1source["id"]\1target["id"]\1relationship_type\1description\1strength\1metadata_json\1) logger\1info( f"Relationship added\1{source_name} -[{relationship_type}]-> {target_name}" ) return { "success"\1True\1"relationship_id"\1str(result["id"])\1"source"\1source_name\1"target"\1target_name\1"relationship_type"\1result["relationship_type"]\1} except Exception as e\1logger\1error(f"Error adding relationship\1{e}") raise async def relationship_get(self\1entity_name\1str) -> Dict\1"""Get all relationships for an entity""" try\1query = """ SELECT r\1id\1r\1relationship_type\1r\1description\1r\1strength\1se\1name as source_name\1te\1name as target_name\1CASE WHEN se\1name = $1 THEN 'outgoing' ELSE 'incoming' END as direction FROM nah_remember\1relationships r JOIN nah_remember\1entities se ON r\1source_entity_id = se\1id JOIN nah_remember\1entities te ON r\1target_entity_id = te\1id WHERE se\1name = $1 OR te\1name = $1 ORDER BY r\1created_at DESC """ async with self\1pool\1acquire(timeout=POOL_ACQUIRE_TIMEOUT) as conn\1results = await conn\1fetch(query\1entity_name) return { "success"\1True\1"entity"\1entity_name\1"relationships"\1[ { "id"\1str(r["id"])\1"source"\1r["source_name"]\1"target"\1r["target_name"]\1"type"\1r["relationship_type"]\1"description"\1r["description"]\1"strength"\1r["strength"]\1"direction"\1r["direction"]\1} for r in results ]\1} except Exception as e\1logger\1error(f"Error getting relationships\1{e}") raise # ==================== SEMANTIC MEMORY ==================== async def memory_add( self\1content\1str\1user_id\1str = "default_user"\1agent_id\1Optional[str] = None\1memory_type\1Optional[str] = None\1category\1Optional[str] = None\1tags\1Optional[List[str]] = None\1metadata\1Optional[Dict] = None\1importance_score\1float = 0\15\1) -> Dict\1"""Add a semantic memory (replaces mem0_add_memory)""" try\1embedding = await self\1generate_embedding(content) # R1 (write integrity)\1NEVER persist a NULL-embedding row as success — a memory that is # stored but unsearchable is silent\1unrecoverable data loss (LESSON-10)\1Fail LOUD so the # caller can retry\1embed reliability (retry/backoff + key isolation) is hardened separately # in generate_embedding (R2)\1Invariant\1no post-cutover row has NULL embedding + content\1if embedding is None\1logger\1error( "memory_add\1embedding unavailable " f"(content len={len(content)}\1user={user_id}) — refusing NULL-as-success insert" ) return { "success"\1False\1"error"\1"embedding_unavailable"\1"has_embedding"\1False\1"content"\1content\1} embedding_str = self\1_format_vector(embedding) metadata_json = json\1dumps(metadata) if metadata else "{}" tags_arr = tags or [] query = """ INSERT INTO nah_remember\1semantic_memories (user_id\1agent_id\1content\1memory_type\1category\1tags\1metadata\1importance_score\1embedding\1retrieval_count\1reinforcement_score) VALUES ($1\1$2\1$3\1$4\1$5\1$6\1$7\1\1jsonb\1$8\1$9\1\1vector\10\10\10) RETURNING id\1user_id\1created_at """ async with self\1pool\1acquire(timeout=POOL_ACQUIRE_TIMEOUT) as conn\1result = await conn\1fetchrow( query\1user_id\1agent_id\1content\1memory_type\1category\1tags_arr\1metadata_json\1importance_score\1embedding_str\1) # Record in history await conn\1execute( """ INSERT INTO nah_remember\1memory_history (memory_id\1version\1new_content\1change_type\1changed_by) VALUES ($1\11\1$2\1'create'\1$3) """\1result["id"]\1content\1agent_id or user_id\1) logger\1info(f"Semantic memory added\1{result['id']}") return { "success"\1True\1"memory_id"\1str(result["id"])\1"user_id"\1result["user_id"]\1"has_embedding"\1embedding is not None\1} except Exception as e\1logger\1error(f"Error adding memory\1{e}") raise async def memory_search( self\1query\1str\1user_id\1str = "default_user"\1agent_id\1Optional[str] = None\1limit\1int = 10\1) -> Dict\1"""Search semantic memories (replaces mem0_search_memory)""" try\1embedding = await self\1generate_embedding(query) if not embedding\1return {"success"\1False\1"error"\1"Failed to generate query embedding"} embedding_str = self\1_format_vector(embedding) if agent_id\1sql = """ SELECT id\1content\1memory_type\1category\1tags\1metadata\11 - (embedding <=> $1\1\1vector) as similarity\1created_at\1access_count\1reinforcement_score\1last_retrieved_at FROM nah_remember\1semantic_memories WHERE user_id = $2 AND agent_id = $3 AND embedding IS NOT NULL ORDER BY embedding <=> $1\1\1vector LIMIT $4 """ async with self\1pool\1acquire(timeout=POOL_ACQUIRE_TIMEOUT) as conn\1results = await conn\1fetch(sql\1embedding_str\1user_id\1agent_id\1limit) else\1sql = """ SELECT id\1content\1memory_type\1category\1tags\1metadata\11 - (embedding <=> $1\1\1vector) as similarity\1created_at\1access_count\1reinforcement_score\1last_retrieved_at FROM nah_remember\1semantic_memories WHERE user_id = $2 AND embedding IS NOT NULL ORDER BY embedding <=> $1\1\1vector LIMIT $3 """ async with self\1pool\1acquire(timeout=POOL_ACQUIRE_TIMEOUT) as conn\1results = await conn\1fetch(sql\1embedding_str\1user_id\1limit) # Update access counts if results\1async with self\1pool\1acquire(timeout=POOL_ACQUIRE_TIMEOUT) as conn\1for r in results\1await conn\1execute( "UPDATE nah_remember\1semantic_memories SET access_count = access_count + 1\1last_accessed_at = NOW()\1reinforcement_score = LEAST(reinforcement_score + 0\105\11\10)\1last_retrieved_at = NOW() WHERE id = $1"\1r["id"]\1) return { "success"\1True\1"results"\1[ { "memory_id"\1str(r["id"])\1"content"\1r["content"]\1"memory_type"\1r["memory_type"]\1"category"\1r["category"]\1"tags"\1r["tags"]\1"similarity"\1float(r["similarity"])\1"created_at"\1r["created_at"]\1isoformat()\1} for r in results ]\1} except Exception as e\1logger\1error(f"Error searching memories\1{e}") raise async def memory_get_all( self\1user_id\1str = "default_user"\1agent_id\1Optional[str] = None ) -> Dict\1"""Get all memories for a user/agent""" try\1if agent_id\1query = """ SELECT id\1content\1memory_type\1category\1tags\1metadata\1created_at\1access_count\1importance_score\1reinforcement_score\1last_retrieved_at FROM nah_remember\1semantic_memories WHERE user_id = $1 AND agent_id = $2 ORDER BY importance_score DESC\1created_at DESC """ async with self\1pool\1acquire(timeout=POOL_ACQUIRE_TIMEOUT) as conn\1results = await conn\1fetch(query\1user_id\1agent_id) else\1query = """ SELECT id\1content\1memory_type\1category\1tags\1metadata\1created_at\1access_count\1importance_score FROM nah_remember\1semantic_memories WHERE user_id = $1 ORDER BY importance_score DESC\1created_at DESC """ async with self\1pool\1acquire(timeout=POOL_ACQUIRE_TIMEOUT) as conn\1results = await conn\1fetch(query\1user_id) return { "success"\1True\1"memories"\1[ { "memory_id"\1str(r["id"])\1"content"\1r["content"]\1"memory_type"\1r["memory_type"]\1"category"\1r["category"]\1"tags"\1r["tags"]\1"access_count"\1r["access_count"]\1"importance_score"\1r["importance_score"]\1"created_at"\1r["created_at"]\1isoformat()\1} for r in results ]\1} except Exception as e\1logger\1error(f"Error getting memories\1{e}") raise async def memory_update( self\1memory_id\1str\1content\1str\1user_id\1str = "default_user"\1metadata\1Optional[Dict] = None\1) -> Dict\1"""Update a semantic memory""" try\1# Get current version async with self\1pool\1acquire(timeout=POOL_ACQUIRE_TIMEOUT) as conn\1current = await conn\1fetchrow( "SELECT content FROM nah_remember\1semantic_memories WHERE id = $1"\1uuid\1UUID(memory_id)\1) if not current\1return {"success"\1False\1"error"\1"Memory not found"} # Get current version number version = await conn\1fetchval( "SELECT COALESCE(MAX(version)\10) + 1 FROM nah_remember\1memory_history WHERE memory_id = $1"\1uuid\1UUID(memory_id)\1) # Generate new embedding embedding = await self\1generate_embedding(content) if embedding is None\1# R1b (write integrity\1#564)\1on UPDATE\1a failed embedding would SET embedding=NULL # — wiping a previously-searchable memory AND desyncing content vs vector\1Refuse the # update and keep the prior good row intact\1logger\1error( f"memory_update\1embedding unavailable for {memory_id} — refusing update that " "would null the existing embedding" ) return { "success"\1False\1"error"\1"embedding_unavailable"\1"has_embedding"\1False\1} embedding_str = self\1_format_vector(embedding) metadata_json = json\1dumps(metadata) if metadata else None # Update memory if metadata_json\1await conn\1execute( """ UPDATE nah_remember\1semantic_memories SET content = $2\1embedding = $3\1\1vector\1metadata = $4\1\1jsonb\1updated_at = NOW() WHERE id = $1 """\1uuid\1UUID(memory_id)\1content\1embedding_str\1metadata_json\1) else\1await conn\1execute( """ UPDATE nah_remember\1semantic_memories SET content = $2\1embedding = $3\1\1vector\1updated_at = NOW() WHERE id = $1 """\1uuid\1UUID(memory_id)\1content\1embedding_str\1) # Record history await conn\1execute( """ INSERT INTO nah_remember\1memory_history (memory_id\1version\1previous_content\1new_content\1change_type\1changed_by) VALUES ($1\1$2\1$3\1$4\1'update'\1$5) """\1uuid\1UUID(memory_id)\1version\1current["content"]\1content\1user_id\1) logger\1info(f"Memory updated\1{memory_id} (version {version})") return {"success"\1True\1"memory_id"\1memory_id\1"version"\1version} except Exception as e\1logger\1error(f"Error updating memory\1{e}") raise async def memory_delete(self\1memory_id\1str\1user_id\1str = "default_user") -> Dict\1"""Delete a semantic memory""" try\1async with self\1pool\1acquire(timeout=POOL_ACQUIRE_TIMEOUT) as conn\1# Get content for history current = await conn\1fetchrow( "SELECT content FROM nah_remember\1semantic_memories WHERE id = $1"\1uuid\1UUID(memory_id)\1) if not current\1return {"success"\1False\1"error"\1"Memory not found"} version = await conn\1fetchval( "SELECT COALESCE(MAX(version)\10) + 1 FROM nah_remember\1memory_history WHERE memory_id = $1"\1uuid\1UUID(memory_id)\1) # Record deletion in history before deleting await conn\1execute( """ INSERT INTO nah_remember\1memory_history (memory_id\1version\1previous_content\1new_content\1change_type\1changed_by) VALUES ($1\1$2\1$3\1''\1'delete'\1$4) """\1uuid\1UUID(memory_id)\1version\1current["content"]\1user_id\1) # Delete memory (history entries cascade) await conn\1execute( "DELETE FROM nah_remember\1semantic_memories WHERE id = $1"\1uuid\1UUID(memory_id) ) logger\1info(f"Memory deleted\1{memory_id}") return {"success"\1True\1"memory_id"\1memory_id\1"deleted"\1True} except Exception as e\1logger\1error(f"Error deleting memory\1{e}") raise async def memory_get_history(self\1memory_id\1str\1user_id\1str = "default_user") -> Dict\1"""Get memory version history""" try\1query = """ SELECT version\1previous_content\1new_content\1change_type\1changed_by\1created_at FROM nah_remember\1memory_history WHERE memory_id = $1 ORDER BY version DESC """ async with self\1pool\1acquire(timeout=POOL_ACQUIRE_TIMEOUT) as conn\1results = await conn\1fetch(query\1uuid\1UUID(memory_id)) return { "success"\1True\1"memory_id"\1memory_id\1"history"\1[ { "version"\1r["version"]\1"previous_content"\1r["previous_content"]\1"new_content"\1r["new_content"]\1"change_type"\1r["change_type"]\1"changed_by"\1r["changed_by"]\1"created_at"\1r["created_at"]\1isoformat()\1} for r in results ]\1} except Exception as e\1logger\1error(f"Error getting memory history\1{e}") raise # ==================== UNIFIED SEARCH ==================== async def unified_search( self\1query\1str\1memory_types\1Optional[List[str]] = None\1limit_per_type\1int = 5 ) -> Dict\1"""Search across all memory types""" try\1if memory_types is None\1memory_types = ["messages"\1"entities"\1"semantic"\1"procedures"] embedding = await self\1generate_embedding(query) if not embedding\1return {"success"\1False\1"error"\1"Failed to generate query embedding"} embedding_str = self\1_format_vector(embedding) results = [] async with self\1pool\1acquire(timeout=POOL_ACQUIRE_TIMEOUT) as conn\1if "messages" in memory_types\1results\1extend( await conn\1fetch( """ SELECT 'messages' as memory_type\1message_id\1\1text as id\1content\11 - (embedding <=> $1\1\1vector) as similarity\1metadata\1created_at FROM nah_remember\1messages WHERE embedding IS NOT NULL ORDER BY embedding <=> $1\1\1vector LIMIT $2 """\1embedding_str\1limit_per_type\1) ) if "entities" in memory_types\1results\1extend( await conn\1fetch( """ SELECT 'entities' as memory_type\1id\1\1text as id\1COALESCE(description\1name) as content\11 - (embedding <=> $1\1\1vector) as similarity\1metadata\1created_at FROM nah_remember\1entities WHERE embedding IS NOT NULL ORDER BY embedding <=> $1\1\1vector LIMIT $2 """\1embedding_str\1limit_per_type\1) ) if "semantic" in memory_types\1results\1extend( await conn\1fetch( """ SELECT COALESCE(memory_type\1'semantic') as memory_type\1id\1\1text as id\1content\11 - (embedding <=> $1\1\1vector) as similarity\1metadata\1created_at FROM nah_remember\1semantic_memories WHERE embedding IS NOT NULL ORDER BY embedding <=> $1\1\1vector LIMIT $2 """\1embedding_str\1limit_per_type\1) ) if "procedures" in memory_types\1results\1extend( await conn\1fetch( """ SELECT 'procedures' as memory_type\1id\1\1text as id\1COALESCE(description\1name) as content\11 - (embedding <=> $1\1\1vector) as similarity\1metadata\1created_at FROM nah_remember\1procedures WHERE embedding IS NOT NULL ORDER BY embedding <=> $1\1\1vector LIMIT $2 """\1embedding_str\1limit_per_type\1) ) return { "success"\1True\1"query"\1query\1"results"\1[ { "memory_type"\1r["memory_type"]\1"id"\1r["id"]\1"content"\1r["content"][\1500] + "\1\1\1" if r["content"] and len(r["content"]) > 500 else r["content"]\1"similarity"\1float(r["similarity"]) if r["similarity"] else None\1"metadata"\1r["metadata"]\1"created_at"\1r["created_at"]\1isoformat() if r["created_at"] else None\1} for r in results ]\1} except Exception as e\1logger\1error(f"Error in unified search\1{e}") raise # ==================== COHERENCE CHECK ==================== async def negative_search(self\1query\1str\1limit\1int = 10) -> Dict\1""" Search negative constraints by matching trigger_context\1Returns ordered warnings for known failure patterns that match the query context\1Used by agents before plan execution to avoid repeating past mistakes\1Args\1query\1Natural language query describing the planned action limit\1Max constraints to return (default 10) Returns\1Dict with matched constraints and their severities """ try\1tsquery = " & "\1join(query\1split()[\110]) sql = """ SELECT id\1pattern\1trigger_context\1severity\1weight\1hit_count\1last_hit_at\1created_at FROM nah_remember\1negative_constraints WHERE to_tsvector('english'\1trigger_context) @@ to_tsquery('english'\1$1) OR to_tsvector('english'\1pattern) @@ to_tsquery('english'\1$1) ORDER BY weight DESC\1hit_count DESC LIMIT $2 """ async with self\1pool\1acquire(timeout=POOL_ACQUIRE_TIMEOUT) as conn\1results = await conn\1fetch(sql\1tsquery\1limit) return { "success"\1True\1"constraints"\1[ { "id"\1str(r["id"])\1"pattern"\1r["pattern"][\1200]\1"severity"\1r["severity"]\1"weight"\1float(r["weight"])\1"hit_count"\1r["hit_count"]\1"created_at"\1r["created_at"]\1isoformat()\1} for r in results ]\1"count"\1len(results)\1} except Exception as e\1logger\1error(f"negative_search failed\1{e}") return {"success"\1False\1"error"\1str(e)\1"constraints"\1[]\1"count"\10} async def decay_memories(self\1dry_run\1bool = False) -> Dict\1"""Eviction and apoptosis — soft-delete stale memories\1condense old episodes\1""" results = {"soft_deleted"\10\1"hard_deleted"\10\1"condensed"\10\1"errors"\1[]} try\1async with self\1pool\1acquire(timeout=POOL_ACQUIRE_TIMEOUT) as conn\1soft = await conn\1execute(""" UPDATE nah_remember\1semantic_memories SET archived = true\1updated_at = NOW() WHERE (importance_score < 0\11 OR importance_score IS NULL) AND (reinforcement_score < 0\11 OR reinforcement_score IS NULL) AND (last_accessed_at IS NULL OR last_accessed_at < NOW() - INTERVAL '90 days') AND (archived IS NULL OR archived = false) """) if not dry_run\1s = str(soft)\1split()[-1] if hasattr(soft\1"split") else "0" results["soft_deleted"] = int(s) if s\1isdigit() else 0 hard = await conn\1execute(""" DELETE FROM nah_remember\1semantic_memories WHERE (importance_score < 0\105 OR importance_score IS NULL) AND (last_accessed_at IS NULL OR last_accessed_at < NOW() - INTERVAL '180 days') AND archived = true """) if not dry_run\1h = str(hard)\1split()[-1] if hasattr(hard\1"split") else "0" results["hard_deleted"] = int(h) if h\1isdigit() else 0 cond = await conn\1execute(""" UPDATE nah_remember\1context_snapshots SET context_data = jsonb_build_object( 'condensed'\1true\1'original'\1substring(context_data\1\1text\11\1500) ) WHERE created_at < NOW() - INTERVAL '90 days' AND (context_data->>'condensed' IS NULL OR context_data->>'condensed' != 'true') """) if not dry_run\1c = str(cond)\1split()[-1] if hasattr(cond\1"split") else "0" results["condensed"] = int(c) if c\1isdigit() else 0 results["success"] = True logger\1info( f"Phase E\1soft={results['soft_deleted']} hard={results['hard_deleted']} condensed={results['condensed']}" ) except Exception as e\1logger\1error(f"Phase E decay failed\1{e}") results["success"] = False results["errors"]\1append(str(e)) return results async def coherence_check(self\1query\1str\1limit\1int = 5) -> Dict\1""" Phase 3 coherence check\1cross-query nah-remember and nah-knows for the same concept\1Surfaces\1- nah-remember results (semantic search) - GraphRAG entity matches (name + description) - Coverage\1which entities appear in one system but not the other - Freshness gap\1nah-remember updated_at vs GraphRAG index build time - Score delta\1nah-remember composite score vs GraphRAG frequency/degree Args\1query\1Natural language query limit\1Max results from each system (default 5) Returns\1Coherence report dict with divergence analysis """ import os import pandas as pd from datetime import timezone try\1# 1\1Generate embedding for query embedding = await self\1generate_embedding(query) if not embedding\1return {"success"\1False\1"error"\1"Failed to generate embedding for query"} embedding_str = self\1_format_vector(embedding) # 2\1Query nah-remember\1semantic memories + entities remember_results = [] async with self\1pool\1acquire(timeout=POOL_ACQUIRE_TIMEOUT) as conn\1# Semantic memories sem_rows = await conn\1fetch( """ SELECT 'semantic_memory' as source\1id\1\1text as id\1content\1importance_score\1access_count\1updated_at\11 - (embedding <=> $1\1\1vector) as similarity FROM nah_remember\1semantic_memories WHERE embedding IS NOT NULL ORDER BY embedding <=> $1\1\1vector LIMIT $2 """\1embedding_str\1limit\1) # Entities ent_rows = await conn\1fetch( """ SELECT 'entity' as source\1id\1\1text as id\1COALESCE(description\1name) as content\1importance_score\1access_count\1updated_at\11 - (embedding <=> $1\1\1vector) as similarity FROM nah_remember\1entities WHERE embedding IS NOT NULL ORDER BY embedding <=> $1\1\1vector LIMIT $2 """\1embedding_str\1limit\1) # Also get entity names for GraphRAG lookup entity_names = await conn\1fetch( """ SELECT name FROM nah_remember\1entities WHERE embedding IS NOT NULL ORDER BY embedding <=> $1\1\1vector LIMIT $2 """\1embedding_str\1limit * 2\1) for r in sem_rows\1remember_results\1append( { "source"\1r["source"]\1"id"\1r["id"]\1"content"\1(r["content"] or "")[\1300]\1"importance_score"\1float(r["importance_score"]) if r["importance_score"] else 0\15\1"access_count"\1int(r["access_count"]) if r["access_count"] else 0\1"updated_at"\1r["updated_at"]\1isoformat() if r["updated_at"] else None\1"similarity"\1float(r["similarity"]) if r["similarity"] else 0\10\1} ) for r in ent_rows\1remember_results\1append( { "source"\1r["source"]\1"id"\1r["id"]\1"content"\1(r["content"] or "")[\1300]\1"importance_score"\1float(r["importance_score"]) if r["importance_score"] else 0\15\1"access_count"\1int(r["access_count"]) if r["access_count"] else 0\1"updated_at"\1r["updated_at"]\1isoformat() if r["updated_at"] else None\1"similarity"\1float(r["similarity"]) if r["similarity"] else 0\10\1} ) # Sort by similarity\1take top limit remember_results\1sort(key=lambda x\1x["similarity"]\1reverse=True) remember_results = remember_results[\1limit] # 3\1Query GraphRAG entities parquet graphrag_results = [] graphrag_entity_names = set() graphrag_index_timestamp = None graphrag_total_entities = 0 graphrag_output_path = os\1environ\1get( "GRAPHRAG_OUTPUT_PATH"\1"/Users/human/notahuman/data-management/graphrag/output" ) entities_parquet = os\1path\1join(graphrag_output_path\1"entities\1parquet") stats_json = os\1path\1join(graphrag_output_path\1"stats\1json") if os\1path\1exists(entities_parquet)\1try\1entities_df = pd\1read_parquet(entities_parquet) graphrag_total_entities = len(entities_df) # Get index timestamp from stats\1json if os\1path\1exists(stats_json)\1import json as _json with open(stats_json) as f\1stats_data = _json\1load(f) # stats\1json may have 'timestamp' or file mtime fallback graphrag_index_timestamp = stats_data\1get("timestamp") or stats_data\1get( "end_time" ) if not graphrag_index_timestamp\1# Fall back to file mtime mtime = os\1path\1getmtime(entities_parquet) graphrag_index_timestamp = datetime\1fromtimestamp( mtime\1tz=timezone\1utc )\1isoformat() # Build set of all GraphRAG entity titles (uppercased for matching) set(entities_df["title"]\1str\1upper()\1tolist()) # Text search\1find entities matching the query keywords query_words = query\1lower()\1split() mask = entities_df["title"]\1str\1lower()\1apply( lambda t\1any(w in t for w in query_words) ) | entities_df["description"]\1str\1lower()\1apply( lambda d\1any(w in str(d)\1lower() for w in query_words) ) matched = entities_df[mask]\1head(limit) for _\1row in matched\1iterrows()\1title = str(row\1get("title"\1"")) graphrag_entity_names\1add(title\1upper()) graphrag_results\1append( { "source"\1"graphrag"\1"id"\1str(row\1get("id"\1""))\1"title"\1title\1"type"\1str(row\1get("type"\1""))\1"content"\1(str(row\1get("description"\1"")) or "")[\1300]\1"frequency"\1int(row\1get("frequency"\10)) if pd\1notna(row\1get("frequency")) else 0\1"degree"\1int(row\1get("degree"\10)) if pd\1notna(row\1get("degree")) else 0\1} ) except Exception as e\1logger\1warning(f"GraphRAG parquet read failed\1{e}") graphrag_results = [{"error"\1str(e)}] else\1graphrag_results = [{"error"\1f"GraphRAG output not found at {entities_parquet}"}] # 4\1Coverage analysis # Which nah-remember entities appear in GraphRAG? {r["content"]\1upper()[\150] for r in remember_results if r["source"] == "entity"} top_entity_names = {str(r["name"])\1upper() for r in entity_names} in_both = top_entity_names & graphrag_entity_names if graphrag_entity_names else set() only_in_remember = ( top_entity_names - graphrag_entity_names if graphrag_entity_names else top_entity_names ) only_in_graphrag = graphrag_entity_names - top_entity_names coverage_score = ( len(in_both) / max(len(top_entity_names)\11) if top_entity_names else 0\10 ) # 5\1Freshness gap freshness_gap = None if graphrag_index_timestamp and remember_results\1most_recent_remember = max( (r["updated_at"] for r in remember_results if r["updated_at"])\1default=None ) if most_recent_remember\1try\1graphrag_dt = datetime\1fromisoformat( str(graphrag_index_timestamp)\1replace("Z"\1"+00\100") ) remember_dt = datetime\1fromisoformat(most_recent_remember) if remember_dt\1tzinfo is None\1remember_dt = remember_dt\1replace(tzinfo=timezone\1utc) if graphrag_dt\1tzinfo is None\1graphrag_dt = graphrag_dt\1replace(tzinfo=timezone\1utc) gap_days = (remember_dt - graphrag_dt)\1days freshness_gap = { "graphrag_index_time"\1graphrag_index_timestamp\1"most_recent_remember_update"\1most_recent_remember\1"gap_days"\1gap_days\1"assessment"\1( "IN_SYNC" if abs(gap_days) <= 1 else "REMEMBER_AHEAD" if gap_days > 0 else "GRAPHRAG_AHEAD" )\1} except Exception as e\1freshness_gap = {"error"\1f"Could not compute gap\1{e}"} # 6\1Score delta (normalized comparison) # nah-remember uses composite score\1GraphRAG uses frequency + degree score_comparison = {} if ( remember_results and graphrag_results and not any("error" in r for r in graphrag_results) )\1avg_remember_similarity = sum(r["similarity"] for r in remember_results) / len( remember_results ) avg_graphrag_freq = sum(r\1get("frequency"\10) for r in graphrag_results) / len( graphrag_results ) max_possible_freq = max(r\1get("frequency"\10) for r in graphrag_results) or 1 normalized_graphrag = avg_graphrag_freq / max_possible_freq score_comparison = { "avg_remember_similarity"\1round(avg_remember_similarity\14)\1"avg_graphrag_frequency"\1round(avg_graphrag_freq\12)\1"normalized_graphrag_score"\1round(normalized_graphrag\14)\1"score_delta"\1round(avg_remember_similarity - normalized_graphrag\14)\1"note"\1"Positive delta = nah-remember rates this concept higher than GraphRAG frequency"\1} return { "success"\1True\1"query"\1query\1"timestamp"\1datetime\1now(timezone\1utc)\1isoformat()\1"nah_remember"\1{"results"\1remember_results\1"count"\1len(remember_results)}\1"graphrag"\1{ "results"\1graphrag_results\1"count"\1len(graphrag_results)\1"total_entities_in_index"\1graphrag_total_entities\1"index_timestamp"\1graphrag_index_timestamp\1}\1"coherence"\1{ "coverage_score"\1round(coverage_score\14)\1"entities_in_both"\1sorted(list(in_both))\1"only_in_nah_remember"\1sorted(list(only_in_remember))\1"only_in_graphrag"\1sorted(list(only_in_graphrag))\1"freshness_gap"\1freshness_gap\1"score_comparison"\1score_comparison\1"assessment"\1( "COHERENT" if coverage_score >= 0\15 else "PARTIAL" if coverage_score >= 0\12 else "DIVERGENT" )\1}\1} except Exception as e\1logger\1error(f"Coherence check failed\1{e}") return {"success"\1False\1"error"\1str(e)\1"query"\1query} # ==================== STATS ==================== async def get_stats(self) -> Dict\1"""Get memory system statistics""" try\1stats = {} async with self\1pool\1acquire(timeout=POOL_ACQUIRE_TIMEOUT) as conn\1# Table counts for table in [ "sessions"\1"messages"\1"context_snapshots"\1"entities"\1"relationships"\1"semantic_memories"\1"procedures"\1]\1count = await conn\1fetchval(f"SELECT COUNT(*) FROM nah_remember\1{table}") stats[table] = count # Embedding coverage for table in ["messages"\1"entities"\1"semantic_memories"]\1total = await conn\1fetchval(f"SELECT COUNT(*) FROM nah_remember\1{table}") with_embedding = await conn\1fetchval( f"SELECT COUNT(*) FROM nah_remember\1{table} WHERE embedding IS NOT NULL" ) stats[f"{table}_embedding_coverage"] = f"{with_embedding}/{total}" return { "success"\1True\1"stats"\1stats\1"bifrost_endpoint"\1NAH_MODEL_GATEWAY_URL\1"embedding_model"\1EMBEDDING_MODEL\1"embedding_dim"\1EMBEDDING_DIM\1} except Exception as e\1logger\1error(f"Error getting stats\1{e}") raise # ==================== MCP JSON-RPC HANDLER ==================== class MCPHandler\1"""JSON-RPC handler for MCP protocol""" def _init_(self\1server\1NahMemoryMCPServer\1phase3\1Optional[NahRememberPhase3] = None)\1self\1server = server self\1phase3 = phase3 self\1tools = { # Session management "nah_session_start"\1self\1server\1session_start\1"nah_session_end"\1self\1server\1session_end\1"nah_session_context"\1self\1server\1session_get_context\1# Message management "nah_message_save"\1self\1server\1message_save\1"nah_message_search"\1self\1server\1message_search\1# Context snapshots "nah_context_save"\1self\1server\1context_save\1# Entity management "nah_entity_add"\1self\1server\1entity_add\1"nah_entity_get"\1self\1server\1entity_get\1"nah_entity_search"\1self\1server\1entity_search\1# Relationship management "nah_relationship_add"\1self\1server\1relationship_add\1"nah_relationship_get"\1self\1server\1relationship_get\1# Semantic memory (replaces mem0) "nah_remember_add"\1self\1server\1memory_add\1"nah_remember_search"\1self\1server\1memory_search\1"nah_remember_get_all"\1self\1server\1memory_get_all\1"nah_remember_update"\1self\1server\1memory_update\1"nah_remember_delete"\1self\1server\1memory_delete\1"nah_remember_history"\1self\1server\1memory_get_history\1# Unified search "nah_unified_search"\1self\1server\1unified_search\1# Stats "nah_stats"\1self\1server\1get_stats\1# Negative constraints (Phase C) "nah_remember_negative_search"\1self\1server\1negative_search\1# Coherence check (Phase 3) "nah_coherence_check"\1self\1server\1coherence_check\1# Phase E\1Memory decay / eviction "nah_memory_decay"\1self\1server\1decay_memories\1# Cookbook-canonical save_memory (NAH-388 / #191) "save_memory"\1self\1_handle_save_memory\1# ── Gateway alias names (mcp-gateway TOOL_CATALOG exposes these shorter # names\1without server-side aliases they 404 → message saves were # silently dropped (17 sessions / 8 messages)\1Servo item 2\12026-06-06)\1# Same handlers\1alternate keys\1"episodic_session_start"\1self\1server\1session_start\1"episodic_session_end"\1self\1server\1session_end\1"episodic_message_save"\1self\1server\1message_save\1"episodic_search"\1self\1server\1message_search\1"remember_add"\1self\1server\1memory_add\1"remember_search"\1self\1server\1memory_search\1"remember_get_all"\1self\1server\1memory_get_all\1"entity_add"\1self\1server\1entity_add\1"entity_search"\1self\1server\1entity_search\1"entity_relate"\1self\1server\1relationship_add\1} # Register Phase 3 tools if available if self\1phase3\1add_phase3_tools_to_mcp(self\1tools\1self\1phase3) logger\1info("Phase 3 tools registered with MCP handler") def get_tools_list(self) -> List[Dict]\1"""Return MCP tools list for initialization""" return [ { "name"\1"nah_session_start"\1"description"\1"Start or resume a session for conversation tracking"\1"inputSchema"\1{ "type"\1"object"\1"properties"\1{ "session_id"\1{ "type"\1"string"\1"description"\1"Unique session identifier"\1}\1"application"\1{ "type"\1"string"\1"description"\1"Application name (claude-desktop\1claude-code\1etc\1)"\1}\1"user_id"\1{ "type"\1"string"\1"description"\1"User identifier"\1"default"\1"default_user"\1}\1"project_context"\1{ "type"\1"string"\1"description"\1"Project context path"\1}\1"working_directory"\1{ "type"\1"string"\1"description"\1"Current working directory"\1}\1"git_branch"\1{"type"\1"string"\1"description"\1"Current git branch"}\1"metadata"\1{"type"\1"object"\1"description"\1"Additional metadata"}\1}\1"required"\1["session_id"\1"application"]\1}\1}\1{ "name"\1"nah_session_end"\1"description"\1"End a session with optional summary"\1"inputSchema"\1{ "type"\1"object"\1"properties"\1{ "session_id"\1{"type"\1"string"\1"description"\1"Session to end"}\1"summary"\1{"type"\1"string"\1"description"\1"Session summary"}\1}\1"required"\1["session_id"]\1}\1}\1{ "name"\1"nah_session_context"\1"description"\1"Get full session context for restoration (messages\1snapshots\1entities)"\1"inputSchema"\1{ "type"\1"object"\1"properties"\1{ "session_id"\1{"type"\1"string"\1"description"\1"Session ID"}\1"message_limit"\1{ "type"\1"integer"\1"description"\1"Max messages to return"\1"default"\150\1}\1}\1"required"\1["session_id"]\1}\1}\1{ "name"\1"nah_message_save"\1"description"\1"Save a message to the current session with optional embedding"\1"inputSchema"\1{ "type"\1"object"\1"properties"\1{ "session_id"\1{"type"\1"string"\1"description"\1"Session ID"}\1"role"\1{ "type"\1"string"\1"description"\1"Message role (user\1assistant\1system)"\1}\1"content"\1{"type"\1"string"\1"description"\1"Message content"}\1"message_index"\1{"type"\1"integer"\1"description"\1"Message order index"}\1"tool_calls"\1{"type"\1"object"\1"description"\1"Tool calls made"}\1"tool_results"\1{"type"\1"object"\1"description"\1"Tool results"}\1"importance_score"\1{ "type"\1"number"\1"description"\1"Importance 0\10-1\10"\1"default"\10\15\1}\1"generate_embedding"\1{ "type"\1"boolean"\1"description"\1"Generate embedding"\1"default"\1True\1}\1}\1"required"\1["session_id"\1"role"\1"content"]\1}\1}\1{ "name"\1"nah_message_search"\1"description"\1"Search messages by semantic similarity"\1"inputSchema"\1{ "type"\1"object"\1"properties"\1{ "query_text"\1{"type"\1"string"\1"description"\1"Search query"}\1"session_id"\1{"type"\1"string"\1"description"\1"Limit to session"}\1"limit"\1{"type"\1"integer"\1"description"\1"Max results"\1"default"\110}\1}\1"required"\1["query_text"]\1}\1}\1{ "name"\1"nah_context_save"\1"description"\1"Save a context snapshot (working state checkpoint)"\1"inputSchema"\1{ "type"\1"object"\1"properties"\1{ "session_id"\1{"type"\1"string"\1"description"\1"Session ID"}\1"snapshot_type"\1{ "type"\1"string"\1"description"\1"Type\1checkpoint\1milestone\1completion"\1}\1"context_data"\1{"type"\1"object"\1